"""
Solar Sentry - Environment Prediction Model
Multi-horizon (15/30/60 min) observation quality and atmospheric forecasts.
Adheres strictly to docs/contracts/ObservationQualityPrediction.json.
"""

from datetime import datetime, timezone
from typing import Optional
from sqlalchemy import String, Integer, Float, ForeignKey, Index
from sqlalchemy.orm import Mapped, mapped_column, relationship

from backend.database.core import Base, UTCDateTime, PortableJSON


class EnvironmentPrediction(Base):
    """Authoritative forecast of observation conditions generated by Environment AI."""
    __tablename__ = "environment_predictions"

    prediction_id: Mapped[str] = mapped_column(String(64), primary_key=True)
    device_id: Mapped[str] = mapped_column(
        String(64),
        ForeignKey("devices.device_id", ondelete="CASCADE"),
        nullable=False,
        index=True,
    )
    generated_at: Mapped[datetime] = mapped_column(UTCDateTime, nullable=False, index=True)
    target_timestamp: Mapped[datetime] = mapped_column(UTCDateTime, nullable=False, index=True)
    horizon_minutes: Mapped[int] = mapped_column(Integer, nullable=False)  # 15, 30, 60
    predicted_quality_score: Mapped[float] = mapped_column(Float, nullable=False)  # 0.0 - 1.0 or 0.0 - 100.0
    predicted_cloud_cover_pct: Mapped[float] = mapped_column(Float, nullable=False)
    predicted_lux: Mapped[Optional[float]] = mapped_column(Float, nullable=True)
    rain_probability: Mapped[float] = mapped_column(Float, nullable=False, default=0.0)  # 0.0 - 1.0
    confidence: Mapped[Optional[float]] = mapped_column(Float, nullable=True, default=1.0)  # 0.0 - 1.0
    risk: Mapped[Optional[str]] = mapped_column(String(32), nullable=True, default="LOW")  # LOW, MEDIUM, HIGH, CRITICAL
    model_version: Mapped[str] = mapped_column(String(64), nullable=False, index=True)
    uncertainty_bounds_json: Mapped[Optional[dict]] = mapped_column(PortableJSON, nullable=True)
    created_at: Mapped[datetime] = mapped_column(
        UTCDateTime,
        nullable=False,
        default=lambda: datetime.now(timezone.utc),
    )

    # Relationships
    device: Mapped["Device"] = relationship("Device", back_populates="predictions")

    __table_args__ = (
        Index("ix_predictions_target_horizon", "target_timestamp", "horizon_minutes"),
        Index("ix_predictions_device_generated", "device_id", "generated_at"),
        Index("ix_predictions_risk", "risk"),
    )
